import React from 'react';
import { Typography, Card, CardContent } from '@mui/material';

function WeeklyDigestPage() {
  const digest = {
    total_executions: 184,
    pass_rate: 92,
    fail_rate: 8,
    quality_score: 88,
    recommendations: [
      'Investigate checkout timeouts during peak traffic.',
      'Stabilize login tests by reducing dependency flakiness.',
      'Add more coverage around search race conditions.',
    ],
  };

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Weekly Digest
      </Typography>
      <Card>
        <CardContent>
          <Typography>Total Executions: {digest.total_executions}</Typography>
          <Typography>Pass Rate: {digest.pass_rate}%</Typography>
          <Typography>Fail Rate: {digest.fail_rate}%</Typography>
          <Typography>Quality Score: {digest.quality_score}</Typography>
          <Typography>Recommendation Summary:</Typography>
          <ul>
            {digest.recommendations.map((item, idx) => (
              <li key={idx}>{item}</li>
            ))}
          </ul>
        </CardContent>
      </Card>
    </div>
  );
}

export default WeeklyDigestPage;
